"""Regenerate production_backlog.md from backlog.json (the JSON is the source of truth). Run: python3 render_backlog_md.py"""
import json, os
os.chdir(os.path.dirname(os.path.abspath(__file__)))
B = json.load(open('backlog.json')); L = []
L += ["# Production Backlog — permanent", "",
      "> Source of truth: `backlog.json` (this file is generated by `render_backlog_md.py`).",
      "> Rule: topics are never removed or silently replaced. Rejected topics stay listed with status and reason.", "",
      f"Updated: {B['updated']} · Status flow: {' → '.join(B['status_flow'])}", "",
      "Validation: **Unvalidated** = comparable-video research not yet done (no audience data claimed).", "",
      "## In production", ""]
for e in B['in_production']:
    L.append(f"- **{e['id']} {e['working_title']}** ({e['category']}) — {e['production_status']} · credits spent {e['credits_spent']} · `{e['story_folder']}`")
L += ["", "## Summary", "", "| ID | Title | Category | Dur (s) | Credits | Days | Score | Research | Status |", "|---|---|---|---|---|---|---|---|---|"]
for e in B['backlog']:
    L.append(f"| {e['id']} | {e['working_title']} | {e['category']} | {e['target_duration_s']} | ~{e['estimated_credits']} | {e['estimated_production_days']} | {e['editorial_score'] or '—'} | {e['research_status']} | {e['production_status']} |")
for e in B['backlog']:
    L += ["", f"## {e['id']} — {e['working_title']}", "",
          f"- **Category:** {e['category']}", f"- **Premise:** {e['premise']}", "- **Hooks:**"] + [f"  {i+1}. {h}" for i, h in enumerate(e['hooks'])]
    L += [f"- **Target duration:** {e['target_duration_s']} s", "- **Emotional arc:**"] + [f"  - {a}" for a in e['emotional_arc']]
    for k, lab in [('key_visual_moments', 'Key visual moments'), ('characters', 'Characters'), ('environments', 'Environments'), ('props_and_effects', 'Props / effects'),
                   ('reusable_assets', 'Reusable assets'), ('research_sources', 'Research sources'), ('factual_caveats', 'Factual caveats')]:
        L.append(f"- **{lab}:** " + "; ".join(e[k]))
    L += [f"- **Estimated cost:** ~{e['estimated_credits']} Higgsfield credits (narration + score) · ~{e['estimated_production_days']} production days",
          f"- **Editorial score:** {e['editorial_score'] or 'not yet scored'} · **Research:** {e['research_status']} · **Status:** {e['production_status']}",
          f"- **Publication URL:** {e['publication_url'] or '—'} · **Performance:** {e['performance'] or '—'}"]
    if e.get('notes'): L.append(f"- **Notes:** {e['notes']}")
open('production_backlog.md', 'w').write('\n'.join(L) + '\n'); print(len(L), 'lines')
